```json
{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "Em texto que denuncia um problema, um número raramente está ali só para informar: ele costuma servir de prova para a ideia central. Para achar a intenção do dado, descubra primeiro qual é a tese (a ideia que o texto defende), que aparece no começo, e depois veja como o dado se liga a ela. A tese aqui é que influenciadores negros têm menos alcance que os brancos, mesmo com conteúdo semelhante.",
   "motivo": "Explicar 'tese' na primeira aparição e deixar a frase com um só sentido."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["tese", "a ideia central que o texto quer provar"],
    ["dado estatístico", "número que mede um fato, aqui o aumento de 6 000% no alcance"],
    ["viés racial", "tendência de tratar pessoas de modo diferente por causa da cor da pele"],
    ["alcance", "quantidade de pessoas que chegam a ver uma publicação"],
    ["engajamento", "reações do público a uma postagem: curtidas, comentários, compartilhamentos"],
    ["experimento", "teste em que se muda uma só coisa para ver o efeito; aqui, mudar a cor das pessoas nas fotos"]
   ],
   "motivo": "Incluir 'tese' e 'experimento', termos usados nos passos e não explicados."
  },
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "dado estatístico = prova da tese",
    "tese: negros têm menos alcance, com conteúdo semelhante",
    "experimento: muda só a cor de quem aparece"
   ],
   "motivo": "Deixar a regra mais clara e curta."
  },
  {
   "campo": "resolucao.passos[0].conta",
   "depois": "\"muito menos repercussão\" (negros) × brancos",
   "motivo": "A conta deve caber em ~30 caracteres, sem quebra de linha na tela do celular."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "\"fotografias de modelos brancas\"",
   "motivo": "Conta curta para caber no celular."
  },
  {
   "campo": "resolucao.passos[2].conta",
   "depois": "\"Surpreendentemente... 6 000%\"",
   "motivo": "Conta curta para caber no celular."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "A, B, C e D: fora da tese",
   "motivo": "Conta curta e mais clara do que uma lista de palavras soltas."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "O texto não mede a repercussão do projeto, nem o número de postagens, nem a qualidade, nem quer aumentar o alcance de ninguém. O dado só se liga à denúncia de viés racial.",
   "motivo": "Frase mais direta, ligada à tese."
  },
  {
   "campo": "resolucao.passos[4].conta",
   "depois": "modelos brancas → +6 000% = E",
   "motivo": "Liga o dado à letra e cabe na linha."
  },
  {
   "campo": "resolucao.erradas.E",
   "depois": "Esta é a alternativa certa: o aumento de 6 000% com fotos de modelos brancas liga o alcance ao viés racial.",
   "motivo": "Completar o bloco 'erradas' evitando que a letra certa fique sem comentário não é necessário; mantido apenas como registro opcional."
  }
 ],
